I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
# Find subgrids of I whose nonzero pattern... check for each candidate: rows r..r+7 cols c..c+4 with all cells either matching O or zero? and then infer rule.
hits=[]
for r in range(len(I)-7):
    for c in range(len(I[0])-4):
        ok=all((I[r+i][c+j]==O[i][j] or I[r+i][c+j]==0) for i in range(8) for j in range(5))
        if ok and any(I[r+i][c+j]==0 for i in range(8) for j in range(5)): hits.append((r,c))
print(hits[:10], len(hits))
